def declarees() -> set[tuple[str, str]]:
    """Les arêtes (table, fichier) déclarées finement."""
    return {(x.table, x.fichier) for x in LECTURES}


def lectures_de(table: str) -> list[Lecture]:
    return [x for x in LECTURES if x.table == table]
